import{_ as s,o as a,c as t,af as l}from"./chunks/framework.BSym9njW.js";const k=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"zh/00-environment/lemonade.md","filePath":"zh/00-environment/lemonade.md","lastUpdated":1789547203000}'),i={name:"zh/00-environment/lemonade.md"};function n(d,e,r,p,o,h){return a(),t("div",null,[...e[0]||(e[0]=[l(`<h2 id="lemonade-环境配置-ubuntu-24-04" tabindex="-1">Lemonade 环境配置（Ubuntu 24.04） <a class="header-anchor" href="#lemonade-环境配置-ubuntu-24-04" aria-label="Permalink to &quot;Lemonade 环境配置（Ubuntu 24.04）&quot;">​</a></h2><p>本节介绍在 Ubuntu 24.04 上安装 <a href="https://github.com/lemonade-sdk/lemonade" target="_blank" rel="noreferrer">Lemonade Server</a>，提供 OpenAI 兼容 API 和 Web UI。GPU 走 llama.cpp，NPU 走 FastFlowLM。本页只装环境和后端；拉模见 <a href="/hello-rocm/zh/01-deploy/">01-Deploy</a>。</p><blockquote><p>官方文档：<a href="https://lemonade-server.ai/docs/guide/install/ubuntu/" target="_blank" rel="noreferrer">Ubuntu 安装</a> · <a href="https://lemonade-server.ai/flm_npu_linux.html" target="_blank" rel="noreferrer">Linux NPU / FLM</a></p><p>NPU 驱动与 IOMMU 的细账在 <a href="./fastflowlm">FastFlowLM 环境</a>。Lemonade 只是调用已装好的 <code>flm</code>。</p></blockquote><hr><h3 id="本教程验证基线-2026-09-16" tabindex="-1">本教程验证基线（2026-09-16） <a class="header-anchor" href="#本教程验证基线-2026-09-16" aria-label="Permalink to &quot;本教程验证基线（2026-09-16）&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">项</th><th style="text-align:left;">值</th></tr></thead><tbody><tr><td style="text-align:left;">包</td><td style="text-align:left;"><code>lemonade-server</code> <strong>11.9.0~24.04</strong></td></tr><tr><td style="text-align:left;">CLI</td><td style="text-align:left;"><code>lemonade version 11.9.0</code></td></tr><tr><td style="text-align:left;">服务</td><td style="text-align:left;"><code>/usr/bin/lemond</code>，默认 <strong>13305</strong></td></tr><tr><td style="text-align:left;">OpenAI</td><td style="text-align:left;"><code>http://127.0.0.1:13305/api/v1</code>（部分客户端也可试 <code>/v1</code>）</td></tr><tr><td style="text-align:left;">GPU 后端</td><td style="text-align:left;"><strong><code>llamacpp:vulkan</code></strong>（实测机 kernel 6.17 上 <code>llamacpp:rocm</code> 报 <em>Linux kernel missing support</em>）</td></tr><tr><td style="text-align:left;">NPU 后端</td><td style="text-align:left;">见下方注意：本教程 <strong>NPU 推荐走原生 FastFlowLM 8219</strong></td></tr><tr><td style="text-align:left;">系统服务</td><td style="text-align:left;"><code>lemond.service</code>（enabled），工作目录 <code>/var/lib/lemonade</code></td></tr></tbody></table><hr><h3 id="_1-安装-server" tabindex="-1">1. 安装 Server <a class="header-anchor" href="#_1-安装-server" aria-label="Permalink to &quot;1. 安装 Server&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">sudo</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> add-apt-repository</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -y</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> ppa:lemonade-team/stable</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">sudo</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> apt</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> update</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">sudo</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> apt</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> install</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -y</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> lemonade-server</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">lemonade</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> --version</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">lemonade</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> status</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>应看到 <code>lemonade version 11.9.0</code>（或更新）。Server 在跑时：<code>Server is running on port 13305</code>。浏览器打开 <code>http://127.0.0.1:13305</code>。</p><p>APT 安装通常会启用 <strong><code>lemond.service</code></strong>（开机自启、用户 <code>lemonade</code>、<code>ProtectHome=yes</code>）。用完可停：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">sudo</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> systemctl</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> stop</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> lemond</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>不要开机自启：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">sudo</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> systemctl</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> disable</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> --now</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> lemond</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><blockquote><p>⚠️ 单位名是 <strong><code>lemond</code></strong>，不是 <code>lemonade-server</code>。</p></blockquote><hr><h3 id="_2-安装推理后端" tabindex="-1">2. 安装推理后端 <a class="header-anchor" href="#_2-安装推理后端" aria-label="Permalink to &quot;2. 安装推理后端&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">lemonade</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> backends</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">lemonade</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> backends</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> install</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> llamacpp:vulkan</span><span style="--shiki-light:#008000;--shiki-dark:#6A9955;">   # 已装可跳过</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">lemonade</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> backends</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><code>llamacpp:rocm</code> 需要内核满足 <a href="https://lemonade-server.ai/gfx1151_linux.html" target="_blank" rel="noreferrer">gfx1151 Linux</a>。不满足时用 Vulkan，不要卡在 ROCm 后端。</p><p><strong>关于 <code>flm:npu</code>：</strong></p><ul><li><code>lemonade backends install flm:npu</code> 会去 GitHub 拉 FLM 包，国内常超时。</li><li>系统里若已有 apt / deb 安装的 <code>flm</code>，systemd 的 <code>lemond.service</code> 以用户 <code>lemonade</code> 运行且 <strong>ProtectHome=yes</strong>，<strong>读不到</strong> <code>~/.config/flm</code>。</li><li>因此本教程 NPU 请走 <a href="./fastflowlm">FastFlowLM 环境</a> + <code>flm serve</code>（端口 <strong>8219</strong>）。</li><li>若你改用登录用户前台跑 <code>lemond</code>（不要 systemd ProtectHome），并成功装上 <code>flm:npu</code>，再尝试 <code>lemonade load &lt;flm-tag&gt;</code>。</li></ul><p>不要 <code>source /opt/rocm</code> 再跑 Lemonade 的 NPU 路径。</p><hr><h3 id="_3-体检" tabindex="-1">3. 体检 <a class="header-anchor" href="#_3-体检" aria-label="Permalink to &quot;3. 体检&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">lemonade</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> --version</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">lemonade</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> status</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">lemonade</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> backends</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">ss</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -tlnp</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;"> | </span><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">grep</span><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;"> 13305</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>可选脚本：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">bash</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> src/npu/scripts/check_lemonade.sh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>NPU 还要另做 FastFlowLM 校验：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">unset</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> ROCM_PATH</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> HIP_PATH</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> LD_LIBRARY_PATH</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">bash</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> src/npu/scripts/check_flm_npu.sh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><hr><h3 id="_4-常用命令" tabindex="-1">4. 常用命令 <a class="header-anchor" href="#_4-常用命令" aria-label="Permalink to &quot;4. 常用命令&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">命令</th><th style="text-align:left;">作用</th></tr></thead><tbody><tr><td style="text-align:left;"><code>lemonade backends</code></td><td style="text-align:left;">已装 / 可装后端</td></tr><tr><td style="text-align:left;"><code>lemonade status</code></td><td style="text-align:left;">Server 是否在 13305、已 load 的模型</td></tr><tr><td style="text-align:left;"><code>lemonade list</code></td><td style="text-align:left;">目录；<code>--downloaded</code> 只看本地</td></tr><tr><td style="text-align:left;"><code>lemonade pull NAME</code></td><td style="text-align:left;">下载（国内可加 <code>--source modelscope</code>）</td></tr><tr><td style="text-align:left;"><code>lemonade load NAME</code></td><td style="text-align:left;">加载到 Server</td></tr><tr><td style="text-align:left;"><code>lemonade unload</code></td><td style="text-align:left;">卸模型</td></tr><tr><td style="text-align:left;"><code>lemonade run NAME</code></td><td style="text-align:left;">load + 打开 Web UI</td></tr><tr><td style="text-align:left;"><code>lemonade chat</code></td><td style="text-align:left;">终端 REPL</td></tr></tbody></table><p>GPU 指定后端：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">lemonade</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> load</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> Gemma-4-E4B-it-GGUF</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> --llamacpp</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> vulkan</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><hr><h3 id="_5-与本教程其它端口" tabindex="-1">5. 与本教程其它端口 <a class="header-anchor" href="#_5-与本教程其它端口" aria-label="Permalink to &quot;5. 与本教程其它端口&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">端口</th><th style="text-align:left;">用途</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>13305</strong></td><td style="text-align:left;">Lemonade Server</td></tr><tr><td style="text-align:left;"><strong>8219</strong></td><td style="text-align:left;">原生 <code>flm serve</code>（与 Lemonade NPU <strong>互斥</strong>）</td></tr><tr><td style="text-align:left;">11434 / 8000 等</td><td style="text-align:left;">Ollama / vLLM 等 GPU 教程，统一内存紧张时不要同时常驻</td></tr></tbody></table><p>下一步：</p><ul><li><a href="/hello-rocm/zh/01-deploy/gemma4/lemonade-gpu-deploy">Gemma 4 Lemonade GPU</a></li><li><a href="/hello-rocm/zh/01-deploy/gemma4/lemonade-npu-deploy">Gemma 4 Lemonade NPU</a></li><li><a href="/hello-rocm/zh/01-deploy/qwen36/lemonade-gpu-deploy">Qwen3.6 Lemonade</a></li><li><a href="./npu-troubleshooting">NPU 排错</a></li></ul>`,40)])])}const m=s(i,[["render",n]]);export{k as __pageData,m as default};
